1	import { BRAND, FONT, type AccentKey } from "@/lib/brand";
2	import type React from "react";
3	
4	interface SectionEyebrowProps {
5	  label: string;
6	  dark?: boolean;
7	  accent?: AccentKey;
8	}
9	
10	const accentColors: Record<AccentKey, string> = {
11	  rust:  BRAND.rust,
12	  sage:  BRAND.sage,
13	  amber: BRAND.amber,
14	};
15	
16	export function SectionEyebrow({ label, dark = false, accent = 'rust' }: SectionEyebrowProps) {
17	  return (
18	    <div style={{
19	      display: 'inline-flex', alignItems: 'center', gap: 8,
20	      padding: '6px 14px', borderRadius: 100,
21	      background: dark ? 'rgba(247,247,245,0.08)' : BRAND.white,
22	      border: dark ? 'none' : `1px solid ${BRAND.border}`,
23	      fontFamily: FONT.sans, fontSize: 12, fontWeight: 500,
24	      color: dark ? BRAND.stoneLight : BRAND.stoneDark,
25	      letterSpacing: '0.02em', marginBottom: 22,
26	      boxShadow: dark ? 'none' : '0 1px 2px rgba(15,15,15,0.04)',
27	    } as React.CSSProperties}>
28	      <span style={{
29	        width: 6, height: 6, borderRadius: 100,
30	        background: dark ? accentColors[accent] : accentColors[accent],
31	      } as React.CSSProperties} />
32	      {label}
33	    </div>
34	  );
35	}
